    assertNotNull(location);
    assertThat(location.getLineNumber(), greaterThan(0));
    assertThat(location.getColumnNumber(), greaterThan(0));
    assertNotNull(location.getSource());
    assertThat(location.getSource().getLocation(), containsString("settings.xml"));
}

@Test
void testProxiedSessionScopedBean() throws ComponentLookupException {
    ComponentLookupException e = assertThrows(ComponentLookupException.class, () -> container.lookup(MySingletonBean2.class));
    assertTrue(e.getMessage().matches("[\\s\\S]*: Can not set .* field .* to [\\s\\S]*"));
    MySingletonBean bean = container.lookup(MySingletonBean.class);
    assertNotNull(bean);
    assertNotNull(bean.anotherBean);
    assertSame(AnotherBean.class, bean.anotherBean.getClass());
    assertNotNull(bean.myBean);
    assertNotSame(MySessionScopedBean.class, bean.myBean.getClass());
    assertThrows(OutOfScopeException.class, () -> bean.myBean.getSession());
    sessionScope.enter();
    sessionScope.seed(Session.class, this.session);
    assertNotNull(bean.myBean.getSession());
    assertNotNull(bean.myBean.getAnotherBean());
    assertSame(AnotherBean.class, bean.myBean.getAnotherBean().getClass());
    assertThrows(TestException.class, () -> bean.myBean.throwException());
}

@Test
void testAsString() {
    InternalSession session = Mockito.mock(InternalSession.class);
    // Create a basic dependency node
    DefaultArtifact artifact = new DefaultArtifact("org.example:myapp:1.0");
    Dependency dependency = new Dependency(artifact, "compile");
    DefaultDependencyNode node = new DefaultDependencyNode(dependency);
    // Test non-verbose mode
    DefaultNode defaultNode = new DefaultNode(session, node, false);
    assertEquals("org.example:myapp:jar:1.0:compile", defaultNode.asString());
    // Test verbose mode with managed version
    node.setData(DependencyManagerUtils.NODE_DATA_PREMANAGED_VERSION, "0.9");
    node.setManagedBits(DependencyNode.MANAGED_VERSION);
    defaultNode = new DefaultNode(session, node, true);
    assertEquals("org.example:myapp:jar:1.0:compile (version managed from 0.9)", defaultNode.asString());
    // Test verbose mode with managed scope
    node.setData(DependencyManagerUtils.NODE_DATA_PREMANAGED_SCOPE, "runtime");
    node.setManagedBits(DependencyNode.MANAGED_VERSION | DependencyNode.MANAGED_SCOPE);
    defaultNode = new DefaultNode(session, node, true);
    assertEquals("org.example:myapp:jar:1.0:compile (version managed from 0.9; scope managed from runtime)", defaultNode.asString());
    // Test verbose mode with conflict resolution
    DefaultDependencyNode winner = new DefaultDependencyNode(new Dependency(new DefaultArtifact("org.example:myapp:2.0"), "compile"));
    node.setData(ConflictResolver.NODE_DATA_WINNER, winner);
    node.setManagedBits(0);
    defaultNode = new DefaultNode(session, node, true);
    assertEquals("(org.example:myapp:jar:1.0:compile - omitted for conflict with 2.0)", defaultNode.asString());
}

