@Test
void testExitResetsParentTrace() {
    InternalSession session = mock(InternalSession.class);
    org.apache.maven.api.services.RequestTrace parentTrace = new org.apache.maven.api.services.RequestTrace(null, "parent");
    org.apache.maven.api.services.RequestTrace currentTrace = new org.apache.maven.api.services.RequestTrace(parentTrace, "current");
    RequestTraceHelper.ResolverTrace resolverTrace = new RequestTraceHelper.ResolverTrace(session, "test", null, currentTrace);
    RequestTraceHelper.exit(resolverTrace);
    verify(session).setCurrentTrace(parentTrace);
}

